package com.vandorlabs.gear.core;
public final class CoreNativeOrientationTest {
 private static int checks;private static void need(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 private static GearMotion.Vec physical(int mount,GearMotion.Vec v){return new GearMotion.Vec(GearMountFrame.x(mount,v.x,v.y,v.z),GearMountFrame.y(mount,v.x,v.y,v.z),GearMountFrame.z(mount,v.x,v.y,v.z));}
 private static GearMotion.Vec local(int mount,int axis){int inverse=mount==2?3:mount==3?2:mount==4?5:mount==5?4:mount;return physical(inverse,new GearMotion.Vec(axis==0?1:0,axis==1?1:0,axis==2?1:0));}
 public static void main(String[] a){CoreNativeOrientation.Cache cache=new CoreNativeOrientation.Cache();for(int mount=0;mount<6;mount++)for(GearMotion.Mode mode:new GearMotion.Mode[]{GearMotion.Mode.ROTATE,GearMotion.Mode.ROTATE_LEVEL})for(ArmHinge.Mode hinge:ArmHinge.Mode.values())for(GearMotion.Direction fold:GearMotion.Direction.values())for(GearMotion.Direction kink:GearMotion.Direction.values())for(double angle:new double[]{-180,-90,-45,0,45,90,180}){GearMotion.Pose pose=GearMotion.pose(mode,fold,5,0,-6,0,13/16D,angle,0,hinge,kink,1);GearMotion.Vec zero=physical(mount,pose.transformFootVertex(0,0,0));int[] basis=new int[9];boolean grid=true;for(int c=0;c<3;c++){GearMotion.Vec p=local(mount,c),v=physical(mount,pose.transformFootVertex(p.x,p.y,p.z));double[] d={v.x-zero.x,v.y-zero.y,v.z-zero.z};for(int r=0;r<3;r++){basis[r*3+c]=(int)Math.rint(d[r]);grid&=Math.abs(d[r]-basis[r*3+c])<1e-8;}}boolean expected=grid&&CoreNativeOrientation.yaw(basis),actual=CoreNativeOrientation.endpoint(mode,mount,fold,angle);need(actual==expected,"actual prepared pose basis "+mount+" "+mode+" "+hinge+" "+fold+" "+kink+" "+angle);need(cache.allows(mode,mount,fold,0,angle,true)==actual,"active cache configuration");need(cache.allows(mode,mount,fold,0,angle,false),"zero native rest always eligible");for(int n=0;n<3;n++)need(cache.allows(mode,mount,fold,0,angle,true)==actual,"repeated cache lookup");}
 need(!CoreNativeOrientation.endpoint(GearMotion.Mode.ROTATE,1,GearMotion.Direction.SOUTH,90),"exact old UP saved ROTATE Double Core keeps raw contact");need(!CoreNativeOrientation.endpoint(GearMotion.Mode.ROTATE,1,GearMotion.Direction.SOUTH,180),"upside-down Core is not native yaw");System.out.println("Core native orientation PASS "+checks+" all6mount/rotate+level/allhinges/fold+kink/native0/upsideDown/cache");}
}
